customCSS:
.t, .history { color: #7b8496; }
.join { color: #5eff6c; }
.part, .quit { color: #7b8496; }
.kick, .error { color: #ff6e5e; }
.notice { color: #f1ff5e; }
.action { color: #bd5eff; }
.mode, .nick, .topic, .server { color: #5ef1ff; }
.highlight { color: #ffffff; background-color: #3c4048; border-left: 3px solid #bd5eff; padding-left: 8px; }
.reply { color: #7b8496; border-left: 2px solid #5ea1ff; padding-left: 6px; }
.oper { color: #16181a; background-color: #f1ff5e; }
.reactions { color: #5ea1ff; background-color: #26292b; }
.card { background-color: #26292b; border-color: #7b8496; }
.card-title { color: #5ea1ff; }
.card-desc { color: #7b8496; }
.daychange { color: #7b8496; border-color: #26292b; }
